    tone(1.95, 1.25, 146.83, 587.33, .19, 'triangle', -.35); sweep(1.95, 1.2, 240, 2600, .37, .3);
    [196,246.94,293.66,392].forEach((f, i) => bell(3.25 + i * .13, f, .34, (i - 1.5) * .28, 1.35));
