    [261.63,329.63,392,523.25].forEach((f, i) => tone(3.25 + i * .13, .43, f, f, .27, 'triangle', (i - 1.5) * .3));
    [783.99,1046.5,1318.51,1567.98].forEach((f, i) => tone(4.03 + i * .11, .2, f, f, .12, 'square', (i - 1.5) * .25, .003));
    [523.25,659.25,1046.5].forEach((f, i) => bell(4.67 + i * .1, f, .075, (i - 1) * .3, .6));
    [523.25,392,329.63,261.63,196].forEach((f, i) => tone(5.78 + i * .2, .12, f, f, .18, 'square', (2 - i) * .2, .004));
