      const x = cx + Math.cos(angle) * r * 1.12, y = cy + Math.sin(angle) * r * .83 + Math.sin(t * 2 + a.phase) * 5;
      const size = a.size * (w < 500 ? .65 : 1), squash = 1 + Math.sin(t * 5 + a.phase) * .1 * (1 - title);
